#!/usr/bin/env bash
# Instalador de traducción completa de Omarchy al español
# Uso: bash ~/omarchy-spanish.sh
# Ejecutar después de cada `omarchy update` si se pierden las traducciones.
#
# Archivos que modifica:
#   ~/.config/omarchy/extensions/menu.sh  — traduce todo el sistema de menús

set -e

BACKUP_BASE="$HOME/.config/omarchy/extensions/backups"
FILES_TO_BACKUP=(
  "$HOME/.config/omarchy/extensions/menu.sh"
)

# ── Menú principal ────────────────────────────────────────────────────────────
echo ""
echo "  Omarchy → Español"
echo "  ──────────────────"
echo "  1) Aplicar traducción española"
echo "  2) Restaurar backup anterior"
echo "  3) Salir"
echo ""
read -rp "  Opción [1/2/3]: " opcion
echo ""

case "$opcion" in
  2)
    # Listar backups disponibles
    if [[ ! -d "$BACKUP_BASE" ]] || [[ -z "$(ls -A "$BACKUP_BASE" 2>/dev/null)" ]]; then
      echo "No hay backups disponibles en $BACKUP_BASE"
      exit 0
    fi

    echo "  Backups disponibles:"
    mapfile -t backups < <(ls -1r "$BACKUP_BASE")
    for i in "${!backups[@]}"; do
      echo "  $((i+1))) ${backups[$i]}"
    done
    echo ""
    read -rp "  Elegí un número [1-${#backups[@]}]: " idx
    echo ""

    if ! [[ "$idx" =~ ^[0-9]+$ ]] || (( idx < 1 || idx > ${#backups[@]} )); then
      echo "Opción inválida."
      exit 1
    fi

    chosen="${BACKUP_BASE}/${backups[$((idx-1))]}"
    echo "  Restaurando desde: $chosen"
    for f in "$chosen"/*; do
      dest="$HOME/.config/omarchy/extensions/$(basename "$f")"
      cp "$f" "$dest"
      echo "  Restaurado: $dest"
    done
    echo ""
    echo "Listo. Restauración completa."
    echo "Si no ves los cambios: omarchy restart walker"
    exit 0
    ;;
  3)
    echo "Saliendo."
    exit 0
    ;;
  1|"")
    : # continúa con la instalación
    ;;
  *)
    echo "Opción inválida."
    exit 1
    ;;
esac

# ── Instalación ───────────────────────────────────────────────────────────────
echo "Aplicando traducción española del menú de Omarchy..."

# Solo hace backup la primera vez (si no existe ninguno previo)
if [[ -z "$(ls -A "$BACKUP_BASE" 2>/dev/null)" ]]; then
  BACKUP_DIR="$BACKUP_BASE/$(date +%Y%m%d_%H%M%S)"
  mkdir -p "$BACKUP_DIR"
  for f in "${FILES_TO_BACKUP[@]}"; do
    if [[ -f "$f" ]]; then
      cp "$f" "$BACKUP_DIR/"
      echo "  Backup (primera vez): $f → $BACKUP_DIR/"
    fi
  done
  echo ""
fi

mkdir -p "$HOME/.config/omarchy/extensions"

python3 << 'EOF'
import base64, os

data = ""

target = os.path.expanduser("~/.config/omarchy/extensions/menu.sh")
with open(target, "wb") as f:
    f.write(base64.b64decode(data))
print("  Escrito:", target)
EOF

echo ""
echo "Listo. El menú de Omarchy está en español."
echo "Si no ves los cambios: omarchy restart walker"
